/* --- CONFIGURATION GLOBALE DU SWITCH --- */
.stealth-switch {
  --w: 80px; /* Largeur */
  --h: 40px; /* Hauteur */
  --handle-size: 34px; /* Taille du bouton rond */
  --p: 3px; /* Padding interne */
  --speed: 0.5s; /* Vitesse fluide */

  /* Couleurs "Luxe" */
  --on-color: #ffb700; /* Or Omega / Ambre */
  --off-metal: #2b2b2b; /* Gris Titane */
  --glow: rgba(255, 183, 0, 0.4);

  display: inline-block;
  position: relative;
  width: var(--w);
  height: var(--h);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  z-index: 1; /* S'assure qu'il est au dessus du reste */
}

/* Cache la checkbox système */
.stealth-switch input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

/* --- LE CORPS (TRACK) --- */
.body {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #111, #1a1a1a);
  border-radius: 50px;
  /* Ombres adaptatives : marchent sur fond blanc ET noir */
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.3),
    /* Ombre portée douce */ inset 0 2px 3px rgba(0, 0, 0, 0.8),
    /* Profondeur interne haute */ inset 0 -1px 1px rgba(255, 255, 255, 0.1); /* Petit reflet bas "Apple" */
  border: 1px solid rgba(255, 255, 255, 0.05); /* Bordure subtile pour fond noir */
  transition: all var(--speed) ease;
  overflow: hidden;
}

/* --- EFFET DE REFLET DE VERRE (SHIMMER) --- */
/* C'est ce qui donne le style "montre de luxe" */
.shimmer {
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.05),
    transparent
  );
  transform: skewX(-20deg);
  transition: left var(--speed) ease;
}

/* --- LE BOUTON (HANDLE) --- */
.handle {
  position: absolute;
  top: var(--p);
  left: var(--p);
  width: var(--handle-size);
  height: var(--handle-size);
  background: conic-gradient(
    from 180deg,
    #444,
    #222,
    #555,
    #222,
    #444
  ); /* Métal brossé */
  border-radius: 50%;
  box-shadow:
    0 2px 5px rgba(0, 0, 0, 0.5),
    inset 0 1px 1px rgba(255, 255, 255, 0.3);
  transition: transform var(--speed) cubic-bezier(0.34, 1.56, 0.64, 1); /* Effet ressort */
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* --- LA LENTILLE CENTRALE (LENS) --- */
/* Le "Cœur" du switch style Batman */
.lens {
  width: 8px;
  height: 8px;
  background-color: #000;
  border-radius: 50%;
  box-shadow: inset 0 1px 2px rgba(255, 255, 255, 0.2);
  transition: all var(--speed) ease;
}

/* --- ÉTAT ACTIVÉ (CHECKED) --- */

/* Mouvement */
.stealth-switch input:checked ~ .handle {
  transform: translateX(calc(var(--w) - var(--handle-size) - (var(--p) * 2)));
}

/* Allumage du fond */
.stealth-switch input:checked ~ .body {
  /* On garde le fond sombre mais on ajoute une lueur interne */
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.3),
    inset 0 2px 3px rgba(0, 0, 0, 0.8),
    inset 0 0 15px var(--glow); /* Lueur diffuse interne */
  border-color: rgba(255, 183, 0, 0.2);
}

/* Mouvement du reflet */
.stealth-switch input:checked ~ .body .shimmer {
  left: 150%; /* Le reflet traverse le switch */
  transition: left 0.8s ease-in-out;
}

/* Allumage de la lentille */
.stealth-switch input:checked ~ .handle .lens {
  background-color: var(--on-color);
  box-shadow:
    0 0 10px var(--on-color),
    inset 0 1px 4px rgba(255, 255, 255, 0.5);
  width: 10px; /* Légère dilatation de la pupille */
  height: 10px;
}

/* Rotation subtile du métal au clic */
.stealth-switch input:checked ~ .handle {
  background: conic-gradient(from 220deg, #444, #222, #555, #222, #444);
}
